let state,selected='',selectedIds=new Set(),refs=new Set(),scale=1,last='',dragging=false,suppressCanvasClick=false,view='home',homeProjectId='',uploading=false,submitting=false,stopping=false,epoch=0,mutating=0,refreshFailures=0,authRedirecting=false,deletedProjectId='',pendingDeleteId='';
function checkSession(response){if(response.status===401){if(!authRedirecting){authRedirecting=true;location.replace('/login?expired=1')}throw Error('登录已过期，请重新登录')}return response}
async function api(path,body){const r=checkSession(await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}));const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data}
async function apiImage(file,preview){if(preview.size>1024*1024)preview=new Blob();const r=checkSession(await fetch('/api/upload-image',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Forma-Project-Id':state.project.id,'X-Forma-File-Name':encodeURIComponent(file.name),'X-Forma-Image-Type':file.type,'X-Forma-Preview-Bytes':String(preview.size)},body:new Blob([preview,file])}));const data=await r.json();if(!r.ok)throw Error(data.error||'上传失败');return data}
function active(){return state?.project.jobs.some(j=>j.status==='running')}
function renderActivity(){
 const activity=$('#activity'),jobs=state?.project.jobs||[],running=jobs.findLast(j=>j.status==='running');
 const recent=jobs.at(-1),showFinished=recent?.status==='completed'&&Date.now()-Date.parse(recent.finishedAt||0)<6000;
 const job=running||(showFinished?recent:null);
 activity.hidden=!job;
 if(!job){activity.dataset.signature='';return}
 const items=job.plan?.items||[],isImage=items.length>0,completed=items.filter(i=>i.status==='completed').length;
 const finished=job.status==='completed',planned=!!job.plan,lastEvent=job.events?.at(-1),saving=isImage&&(lastEvent?.type==='result'||completed===items.length);
 const totalSteps=items.length+2,doneSteps=finished?totalSteps:Number(planned)+completed,percent=Math.floor(doneSteps/totalSteps*100);
 const stage=finished?'已完成':!planned?lastEvent?.type==='planning'?'正在规划方案':'正在理解需求':isImage?saving?'正在保存作品':'正在设计':'正在整理回复';
 const steps=[['理解与规划',planned?'done':'current'],[isImage?'设计作品':'整理回复',finished||isImage&&completed===items.length?'done':planned?'current':'pending'],...(isImage?[['保存作品',finished?'done':saving?'current':'pending']]:[])];
 const signature=JSON.stringify({jobId:job.id,stage,steps,completed,total:items.length,percent});
 if(activity.dataset.signature!==signature){
  activity.dataset.signature=signature;
  activity.innerHTML=`<div class="activity-heading"><span class="activity-pulse ${finished?'finished':''}" aria-hidden="true"></span><strong role="status">${stage}</strong><strong class="activity-percent" title="按已完成步骤计算，不代表剩余时间">${percent}%</strong></div><div class="activity-steps" aria-label="处理阶段">${steps.map(([label,status])=>`<span class="${status}">${status==='done'?'✓ ':''}${label}</span>`).join('')}</div><div class="activity-track" role="progressbar" aria-label="任务步骤完成比例" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-valuetext="已完成 ${doneSteps}/${totalSteps} 个步骤"><span class="activity-fill" style="width:${percent}%"></span>${finished?'':'<span class="activity-flow" aria-hidden="true"></span>'}</div><small class="activity-count">${isImage?`已保存 ${completed}/${items.length} 张 · `:''}已完成 ${doneSteps}/${totalSteps} 个步骤</small>`;
 }
}
function saveDraft(){if(state)sessionStorage.setItem('forma-draft-'+state.project.id,JSON.stringify({text:$('#prompt').value,refs:[...refs]}))}
function loadDraft(){let d={};try{d=JSON.parse(sessionStorage.getItem('forma-draft-'+state.project.id)||'{}')}catch{sessionStorage.removeItem('forma-draft-'+state.project.id)}$('#prompt').value=typeof d?.text==='string'?d.text:'';refs=new Set(Array.isArray(d?.refs)?d.refs:[])}
