function hasSavedImage(job,p){return !!job&&(job.delivery?.delivered>0||p?.assets.some(a=>a.source?.jobId===job.id||a.versions?.some(v=>v.source?.jobId===job.id)))}
function assistantText(m,p){const job=p.jobs.find(j=>j.id===m.jobId);if(['failed','partial'].includes(job?.status)&&hasSavedImage(job,p))return '图片已生成并保存，后续处理暂时中断。你可以在画布上查看或导出作品。';if(job?.status==='completed'&&hasSavedImage(job,p)&&/(请稍等|稍后|马上|接下来|即将)/.test(m.text))return '图片已生成并保存到画布。你可以继续描述想调整的画面，也可以导出 PNG。';return friendly(m.text)}
function friendly(text){if(/用量上限|安心体验/.test(text))return '图片服务已达到账号用量限制，暂时无法生成。你的需求和参考素材已保存。';if(/预算/.test(text))return '当前创作额度已达到上限，你的需求和参考素材已保存。';if(/HTTP|限流|拥堵|API Key|免费模型/.test(text))return '服务暂时繁忙，请稍后继续。你的需求和参考素材已保存。';return text}
function displayAssistantText(text){return String(text??'').replace(/^\s{0,3}#{1,6}\s+/gm,'').replace(/\*\*([^*\n]+)\*\*/g,'$1').replace(/__([^_\n]+)__/g,'$1').replace(/^\s{0,3}[-*]\s+/gm,'• ').replace(/\[([^\]\n]+)\]\((https?:\/\/[^)\s]+)\)/g,'$1（$2）')}
function attachmentMarkup(u){return u.kind==='document'?`<span class="file-tile">▤<small>${esc(u.label)}</small></span>`:`<img src="${u.previewUrl||u.url}" alt="${esc(u.label)}">`}
function render(){const p=state.project;$('#project-name').textContent=p.title||'未命名项目';$('#project-name').title=p.title||'未命名项目';const internal=new Set(p.jobs.filter(j=>/^(initial-verification|verification-schema-fixed)/.test(j.requestId||'')).map(j=>j.text));const scrollAtBottom=$('#messages').scrollHeight-$('#messages').scrollTop-$('#messages').clientHeight<90;const visibleMessages=p.messages.filter((m,i)=>!internal.has(m.text)&&!(m.role==='assistant'&&internal.has(p.messages[i-1]?.text)));$('#messages').innerHTML=visibleMessages.map(m=>`<div class="message ${m.role}"><small>${m.role==='user'?'你':'Forma'}</small>${esc(m.role==='user'?m.text:displayAssistantText(assistantText(m,p)))}${m.role==='user'?`<div class="message-attachments">${(m.attachments||p.jobs.find(j=>j.id===m.jobId||j.text===m.text)?.selection.map(id=>p.uploads.find(u=>u.id===id)).filter(Boolean)||[]).map(u=>`<button type="button" data-preview="${u.id}" title="${esc(u.label)}">${attachmentMarkup(u)}</button>`).join('')}</div>`:''}</div>`).join('');if(scrollAtBottom)$('#messages').scrollTop=$('#messages').scrollHeight;renderActivity();$('#send').disabled=active()||uploading||submitting;$('#file').disabled=active()||uploading||submitting;$('#stop').disabled=stopping;$('#stop').textContent=stopping?'正在停止…':'停止';$('#stop').hidden=!active();$('#send').hidden=!!active();$('#uploads').innerHTML=p.uploads.filter(u=>refs.has(u.id)).map(u=>`<div class="attachment">${attachmentMarkup(u)}<button type="button" data-remove="${u.id}" aria-label="移除参考图 ${esc(u.label)}">×</button>${u.kind==='image'?`<select data-role="${u.id}" aria-label="${esc(u.label)} 的用途"><option value="reference" ${!u.role||u.role==='reference'?'selected':''}>参考图</option><option value="product" ${u.role==='product'?'selected':''}>产品图</option><option value="style" ${u.role==='style'?'selected':''}>风格图</option></select>`:''}</div>`).join('');$('#continue').hidden=hasSavedImage(p.jobs.at(-1),p)||!p.jobs.length||!['failed','cancelled','interrupted'].includes(p.jobs.at(-1).status);$('#count').textContent=p.assets.length?`${p.assets.length} 件作品`:'';
const planned=p.jobs.at(-1)?.plan?.items?.length?p.jobs.at(-1):null;const canContinuePlan=planned&&!active()&&planned.plan.items.some(i=>i.status!=='completed');$('#plan').hidden=!canContinuePlan;$('#plan').innerHTML=canContinuePlan?`<button type="button" id="continue-plan" data-job="${planned.id}">继续未完成图片</button>`:'';$('#empty-chat').hidden=visibleMessages.length>0;$('#empty-canvas').hidden=p.assets.length>0;
$('#send').disabled ||= !$('#prompt').value.trim()&&!refs.size;
$('#recent').innerHTML=(state.projects||[]).slice(0,8).map(p=>`<button data-project="${p.id}" class="${view==='work'&&p.id===state.project.id?'active':''}" ${view==='work'&&p.id===state.project.id?'aria-current="page"':''} title="${esc(p.title||'未命名项目')}">${esc(p.title||'未命名项目')}</button>`).join('');if(view==='projects'||view==='materials')renderLibrary();
$('#canvas').innerHTML=p.assets.map(a=>{const v=a.versions.at(-1),l=v.layer;return `<article class="art ${selectedIds.has(a.id)?'selected':''} ${selectedIds.size>1?'multi-selection':''}" data-id="${a.id}" style="left:${a.x}px;top:${Math.max(160,a.y)}px"><div class="art-title">${esc(a.title)}</div><div class="picture"><img src="${v.image}" draggable="false"><div class="overlay" style="left:${l.x}%;top:${l.y}%;font-size:${l.size/3}px;color:${l.color}">${esc(l.text)}</div></div></article>`}).join('');positionSelectionToolbar()}
function positionSelectionToolbar(){
 const toolbar=$('#editor'),outline=$('#selection-outline'),workspace=$('.workspace'),viewport=$('#viewport');
 const cards=[...selectedIds].map(id=>[...document.querySelectorAll('#canvas .art')].find(el=>el.dataset.id===id)).filter(Boolean);
 if(!cards.length||view!=='work'){toolbar.hidden=true;outline.hidden=true;return}
 const box=workspace.getBoundingClientRect(),visible=viewport.getBoundingClientRect(),rects=cards.map(card=>card.getBoundingClientRect());
 const left=Math.min(...rects.map(rect=>rect.left)),right=Math.max(...rects.map(rect=>rect.right)),top=Math.min(...rects.map(rect=>rect.top)),bottom=Math.max(...rects.map(rect=>rect.bottom));
 if(right<visible.left||left>visible.right||bottom<visible.top||top>visible.bottom){toolbar.hidden=true;outline.hidden=true;return}
 toolbar.hidden=false;const width=toolbar.offsetWidth||180;
 toolbar.style.left=Math.max(8,Math.min((left+right)/2-box.left-width/2,box.width-width-8))+'px';
 toolbar.style.top=Math.max(54,Math.min(top-box.top-54,box.height-54))+'px';
 outline.hidden=cards.length<2;
 if(!outline.hidden){outline.style.left=left-box.left+'px';outline.style.top=top-box.top+'px';outline.style.width=right-left+'px';outline.style.height=bottom-top+'px'}
}
function editor(){const toolbar=$('#editor');if(!selectedIds.size){toolbar.hidden=true;$('#selection-outline').hidden=true;return}toolbar.innerHTML=`<span>${selectedIds.size} 张已选</span><button type="button" id="download-selected" aria-label="下载已选作品">↓ 下载</button>`;$('#download-selected').onclick=()=>downloadSelected().catch(()=>$('#error').textContent='导出失败，请重试。');positionSelectionToolbar()}
function pngData(a){const v=a.versions.at(-1),im=new Image();im.src=v.image;return im.decode().then(()=>{const c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;const ctx=c.getContext('2d');ctx.drawImage(im,0,0);const l=v.layer;if(l?.text){const size=l.size*c.width/1080;ctx.fillStyle=l.color;ctx.font=`600 ${size}px "PingFang SC",sans-serif`;ctx.textBaseline='top';let y=l.y*c.height/100;for(const paragraph of l.text.split('\n')){let line='';for(const char of paragraph){if(ctx.measureText(line+char).width>c.width*.9&&line){ctx.fillText(line,l.x*c.width/100,y);y+=size*1.25;line=''}line+=char}ctx.fillText(line,l.x*c.width/100,y);y+=size*1.25}}return c.toDataURL('image/png')})}
function clickDownload(url,name,revoke=false){const link=document.createElement('a');link.href=url;link.download=name;link.hidden=true;document.body.append(link);link.click();link.remove();if(revoke)setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function exportImage(a){a=state.project.assets.find(item=>item.id===a.id)||a;const data=await pngData(a),result=await api('export',{projectId:state.project.id,id:a.id,data});clickDownload(result.url,a.title+'.png')}
async function downloadSelected(){const assets=state.project.assets.filter(a=>selectedIds.has(a.id)),button=$('#download-selected');if(!assets.length||button?.disabled)return;if(button){button.disabled=true;button.textContent='正在准备下载…'}try{if(assets.length===1){await exportImage(assets[0]);return}const files=[];for(const [index,a] of assets.entries()){const data=await pngData(a),exported=await api('export',{projectId:state.project.id,id:a.id,data});const safeTitle=a.title.replace(/[\/:*?"<>|]/g,'_').slice(0,60)||'作品';files.push({id:a.id,url:exported.url,name:`${String(index+1).padStart(2,'0')}-${safeTitle}.png`})}const result=await api('export-selection',{projectId:state.project.id,files});clickDownload(result.url,`Forma-已选${files.length}张.zip`)}finally{if(button){button.disabled=false;button.textContent='↓ 下载'}}}

function scrollMessagesToLatest(){requestAnimationFrame(()=>{if(view==='work')$('#messages').scrollTop=$('#messages').scrollHeight})}
function setView(next){view=next;if(next==='work')homeProjectId='';document.body.classList.toggle('home-mode',next!=='work');$('#home').hidden=next!=='home';$('#workbench').hidden=next!=='work';$('#library').hidden=!['projects','materials'].includes(next);(next==='work'?$('#work-composer'):$('#home-composer')).append($('#composer'));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('current',b.dataset.view===next));document.querySelectorAll('#recent [data-project]').forEach(b=>{const chosen=next==='work'&&b.dataset.project===state?.project.id;b.classList.toggle('active',chosen);if(chosen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(state&&['projects','materials'].includes(next))renderLibrary();history.replaceState(null,'',next==='work'?'/studio#work':'/studio'+(next==='home'?'':'#'+next));positionSelectionToolbar();if(next==='work')scrollMessagesToLatest()}
function renderLibrary(){$('#library-title').textContent='项目';$('#library-items').innerHTML=(state.projects||[]).map(p=>`<article class="project-card"><button class="project-open" data-project="${p.id}" title="${esc(p.title||'未命名项目')}"><span class="project-cover">${p.cover?`<img src="${p.cover}" alt="" loading="lazy" decoding="async">`:`<span class="project-cover-empty">${esc((p.title||'未命名项目').slice(0,24))}</span>`}</span><span class="project-details"><strong>${esc(p.title||'未命名项目')}</strong></span></button><div class="project-footer"><time>${p.createdAt?new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(p.createdAt)):'创建时间未记录'}</time><details class="project-menu"><summary aria-label="${esc(p.title||'未命名项目')}的更多操作">···</summary><div class="project-menu-popover"><button type="button" data-delete="${p.id}">删除项目</button></div></details></div></article>`).join('');if(!$('#library-items').innerHTML)$('#library-items').innerHTML='<p class="library-empty">还没有项目，点击左侧“新建项目”开始创作。</p>'}
function requestDelete(id){const project=state.projects?.find(p=>p.id===id);if(!project)return;document.querySelectorAll('.project-menu[open]').forEach(menu=>menu.open=false);pendingDeleteId=id;$('#delete-project-name').textContent=project.title||'未命名项目';$('#delete-confirm').showModal()}
async function deleteProject(id){if(active()){$('#error').textContent='请先等待当前创作完成。';return}if(!await action('delete',{id}))return;deletedProjectId=id;$('#undo-delete').hidden=false;if(view==='work')setView('projects');renderLibrary()}
function hasProjectContent(){const p=state?.project;return !!p&&(!!p.messages.length||!!p.uploads.length||!!p.assets.length)}
async function freshHome(){if(uploading||submitting)return false;if(active()){$('#error').textContent='请先等待当前创作完成，或停止后再开始新项目。';setView('work');return false}if(hasProjectContent()&&state.project.id!==homeProjectId){saveDraft();if(!await action('new',{}))return false;refs.clear();selected='';selectedIds.clear();$('#prompt').value='';render();editor()}homeProjectId=state.project.id;setView('home');$('#prompt').focus();return true}
async function ensureHomeProject(){if(view!=='home'||state.project.id===homeProjectId||!hasProjectContent())return true;const text=$('#prompt').value;if(!await action('new',{}))return false;refs.clear();selected='';selectedIds.clear();$('#prompt').value=text;homeProjectId=state.project.id;render();editor();return true}
async function openProject(id){if(uploading||submitting)return;if(id===state.project.id){$('#error').textContent='';setView('work');return}saveDraft();if(!await action('open',{id}))return;loadDraft();selected='';selectedIds.clear();render();editor();setView('work')}
document.addEventListener('click',e=>{const prompt=e.target.closest('[data-prompt]'),nav=e.target.closest('[data-view]'),project=e.target.closest('[data-project]'),remove=e.target.closest('[data-delete]'),material=e.target.closest('[data-material]');if(prompt){$('#prompt').value=prompt.dataset.prompt;saveDraft();$('#prompt').focus()}if(nav){if(nav.dataset.view==='home')freshHome();else setView(nav.dataset.view)}if(remove)requestDelete(remove.dataset.delete);else if(project)openProject(project.dataset.project);if(material){refs.add(material.dataset.material);saveDraft();render();setView('home');$('#prompt').focus()}if(!e.target.closest('.project-menu'))document.querySelectorAll('.project-menu[open]').forEach(menu=>menu.open=false)});
$('#delete-cancel').onclick=()=>{$('#delete-confirm').close();pendingDeleteId=''};
$('#delete-confirm-button').onclick=async()=>{const id=pendingDeleteId;$('#delete-confirm').close();pendingDeleteId='';if(id)await deleteProject(id)};
$('#delete-confirm').addEventListener('close',()=>{pendingDeleteId='' });
$('#new-project').onclick=async()=>{if(uploading){$('#error').textContent='图片上传中，请稍候。';return}if(active()){setView('work');$('#error').textContent='请先等待当前创作完成。';return}saveDraft();if(!await action('new',{}))return;refs.clear();selected='';selectedIds.clear();$('#prompt').value='';render();editor();setView('work');$('#prompt').focus()};$('#undo-delete-button').onclick=async()=>{if(!deletedProjectId)return;const id=deletedProjectId;if(await action('restore',{id})){deletedProjectId='';$('#undo-delete').hidden=true;renderLibrary()}};
$('#chat').onsubmit=async e=>{e.preventDefault();if(uploading||active()||submitting)return;const text=$('#prompt').value.trim()||([...refs].length?'请先看看我上传的素材，帮我梳理可以做什么，并问我下一步想怎么设计。':'');if(!text)return;submitting=true;if(!await ensureHomeProject()){submitting=false;return}saveDraft();render();const ok=await action('run',{text,selection:[...refs,...(selected?[selected]:[])],requestId:crypto.randomUUID()});submitting=false;if(ok){$('#prompt').value='';refs.clear();saveDraft();setView('work');$('#messages').scrollTop=$('#messages').scrollHeight}render()};
$('#stop').onclick=async()=>{if(stopping)return;const job=state.project.jobs.find(j=>j.status==='running');if(!job)return;stopping=true;render();await action('cancel',{jobId:job.id});stopping=false;render()};
$('#prompt').addEventListener('input',()=>{saveDraft();if(state)render()});
let composingPrompt=false;
$('#prompt').addEventListener('compositionstart',()=>{composingPrompt=true});
$('#prompt').addEventListener('compositionend',()=>{composingPrompt=false});
$('#prompt').addEventListener('keydown',e=>{if(e.key!=='Enter'||e.shiftKey||e.ctrlKey||e.metaKey||e.altKey||e.isComposing||composingPrompt||e.keyCode===229)return;e.preventDefault();if(!e.repeat)$('#chat').requestSubmit()});
async function prepareImage(f){const url=URL.createObjectURL(f),im=new Image();try{im.src=url;await im.decode();const scale=Math.min(1,1024/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);return await new Promise((resolve,reject)=>c.toBlob(blob=>blob?resolve(blob):reject(Error('预览图处理失败')),'image/jpeg',.8))}finally{URL.revokeObjectURL(url)}}
async function uploadFiles(files){if(uploading||active()||submitting)return;if(!await ensureHomeProject())return;uploading=true;epoch++;render();const errors=[];let i=0;for(const f of files){i++;$('#upload-status').textContent=`正在上传 ${i} / ${files.length}`;const doc=/\.(txt|md)$/i.test(f.name);if((!doc&&!['image/png','image/jpeg','image/webp'].includes(f.type))||f.size>8*1024*1024){errors.push(`${f.name}：支持 8 MB 以内的图片或 TXT、Markdown 文件`);continue}try{state=doc?await api('upload',{projectId:state.project.id,label:f.name,kind:'document',text:await f.text()}):await apiImage(f,await prepareImage(f));refs.add(state.uploadedId);saveDraft();render()}catch(e){errors.push(`${f.name}：${friendly(e.message)}`)}}uploading=false;$('#upload-status').textContent='';$('#error').textContent=errors.join('；');render()}
$('#file').onchange=e=>{const files=Array.from(e.target.files);e.target.value='';uploadFiles(files)};
$('#chat').ondragover=e=>{e.preventDefault();$('#chat').classList.add('drag-over')};$('#chat').ondragleave=()=>$('#chat').classList.remove('drag-over');$('#chat').ondrop=e=>{e.preventDefault();$('#chat').classList.remove('drag-over');uploadFiles(Array.from(e.dataTransfer.files))};
