$('#uploads').onclick=e=>{const id=e.target.closest('[data-remove]')?.dataset.remove;if(id){refs.delete(id);saveDraft();render()}};
$('#canvas').onclick=e=>{if(suppressCanvasClick){suppressCanvasClick=false;return}if(dragging)return;const art=e.target.closest('.art');if(art){const id=art.dataset.id;if(e.shiftKey||e.metaKey||e.ctrlKey){if(selectedIds.has(id))selectedIds.delete(id);else selectedIds.add(id)}else selectedIds=new Set([id]);selected=selectedIds.has(id)?id:[...selectedIds].at(-1)||''}else{selected='';selectedIds.clear()}render();editor()};
$('#canvas').onpointerdown=e=>{
 if(e.button!==0)return;
 const title=e.target.closest('.art-title');
 if(title&&!active()){const art=title.closest('.art'),a=state.project.assets.find(a=>a.id===art.dataset.id),sx=e.clientX,sy=e.clientY,ox=a.x,oy=Math.max(160,a.y);title.setPointerCapture(e.pointerId);title.onpointermove=ev=>{if(Math.abs(ev.clientX-sx)+Math.abs(ev.clientY-sy)>4)dragging=true;a.x=Math.max(0,ox+(ev.clientX-sx)/scale);a.y=Math.max(160,oy+(ev.clientY-sy)/scale);art.style.left=a.x+'px';art.style.top=a.y+'px';positionSelectionToolbar()};title.onpointerup=()=>{title.onpointermove=null;title.onpointerup=null;if(dragging)action('edit',{id:a.id,position:{x:a.x,y:a.y}});setTimeout(()=>dragging=false,50)};return}
 if(e.target.closest('.art'))return;
 const canvas=$('#canvas'),rect=canvas.getBoundingClientRect(),startX=(e.clientX-rect.left)/scale,startY=(e.clientY-rect.top)/scale;
 const box=document.createElement('div');box.className='selection-marquee';canvas.append(box);canvas.setPointerCapture(e.pointerId);let moved=false;
 const update=ev=>{const x=(ev.clientX-rect.left)/scale,y=(ev.clientY-rect.top)/scale;if(Math.abs(x-startX)+Math.abs(y-startY)>5)moved=true;box.style.left=Math.min(startX,x)+'px';box.style.top=Math.min(startY,y)+'px';box.style.width=Math.abs(x-startX)+'px';box.style.height=Math.abs(y-startY)+'px'};
 canvas.onpointermove=update;canvas.onpointerup=ev=>{update(ev);canvas.onpointermove=null;canvas.onpointerup=null;box.remove();if(!moved)return;const x1=parseFloat(box.style.left),y1=parseFloat(box.style.top),x2=x1+parseFloat(box.style.width),y2=y1+parseFloat(box.style.height);if(!ev.shiftKey&&!ev.metaKey&&!ev.ctrlKey)selectedIds.clear();for(const card of canvas.querySelectorAll('.art')){if(card.offsetLeft<x2&&card.offsetLeft+card.offsetWidth>x1&&card.offsetTop<y2&&card.offsetTop+card.offsetHeight>y1)selectedIds.add(card.dataset.id)}selected=[...selectedIds].at(-1)||'';suppressCanvasClick=true;render();editor()};
 canvas.onpointercancel=()=>{canvas.onpointermove=null;canvas.onpointerup=null;box.remove()};
};
function setCanvasScale(next,clientX,clientY){const viewport=$('#viewport'),rect=viewport.getBoundingClientRect(),x=clientX-rect.left,y=clientY-rect.top,contentX=(viewport.scrollLeft+x)/scale,contentY=(viewport.scrollTop+y)/scale;scale=Math.max(.3,Math.min(1.5,next));$('#canvas').style.transform=`scale(${scale})`;$('#zoom').textContent=Math.round(scale*100)+'%';viewport.scrollLeft=contentX*scale-x;viewport.scrollTop=contentY*scale-y;positionSelectionToolbar()}
function zoom(delta){const rect=$('#viewport').getBoundingClientRect();setCanvasScale(scale+delta,rect.left+rect.width/2,rect.top+rect.height/2)}$('#minus').onclick=()=>zoom(-.1);$('#plus').onclick=()=>zoom(.1);
$('#viewport').addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();setCanvasScale(scale*Math.exp(-e.deltaY*.01),e.clientX,e.clientY)},{passive:false});
$('#viewport').addEventListener('scroll',positionSelectionToolbar);
window.addEventListener('resize',positionSelectionToolbar);
async function refresh(){if(mutating||uploading||authRedirecting)return;const version=epoch;try{const next=await api('state'),signature=JSON.stringify(next);if(version!==epoch||mutating||uploading)return;refreshFailures=0;if($('#error').textContent==='连接暂时中断，正在尝试恢复…')$('#error').textContent='';if(signature!==last&&!dragging){const changed=state&&state.project.id!==next.project.id;state=next;last=signature;if(changed){selected='';selectedIds.clear();loadDraft();editor()}else selectedIds=new Set([...selectedIds].filter(id=>state.project.assets.some(a=>a.id===id)));render()}}catch(e){if(authRedirecting)return;if(++refreshFailures>=3)$('#error').textContent='连接暂时中断，正在尝试恢复…'}}
document.addEventListener('click',e=>{const ref=e.target.closest('[data-preview]');if(ref){const u=state.project.uploads.find(u=>u.id===ref.dataset.preview);if(!u)return;$('#preview-title').textContent=u.label;$('#preview-content').innerHTML=u.kind==='document'?`<pre>${esc(u.text)}</pre>`:`<img src="${u.url}" alt="${esc(u.label)}">`;$('#reference-preview').showModal()}});
$('#preview-close').onclick=()=>$('#reference-preview').close();$('#continue').onclick=()=>{const j=state.project.jobs.at(-1);if(!j||active())return;$('#prompt').value=j.text;refs=new Set(j.selection||[]);saveDraft();render();$('#prompt').focus()};
setView(['work','projects','materials'].includes(location.hash.slice(1))?location.hash.slice(1):'home');await refresh();if(state){loadDraft();render();if(view==='home')await freshHome();else if(view==='work')scrollMessagesToLatest()}setInterval(refresh,1500);setInterval(()=>{if(state)renderActivity()},1000);

